/* ------------------------------------------------------------- confetti */
/*
 * A burst of paper confetti over the solved board before the Solved! dialog: CF_N
 * pieces explode out of the middle of the screen (mostly upwards), air drag slows
 * them, then gravity has them flutter down and away, spinning (drawn as a width
 * that pulses) and fading out at the end. One overlay on the top
 * layer draws them all (its DRAW_MAIN event), redrawn by a timer; it also holds
 * touches back until the dialog is up.
 */
#define CF_N        90                  /**< pieces of confetti */
#define CF_MS       2200                /**< then the dialog */
#define CF_FADE_MS  400                 /**< they fade out over the last this long, ms */

/** @brief A piece of confetti. */
typedef struct {
    float x;                            /**< where, px */
    float y;                            /**< where, px */
    float vx;                           /**< its speed, px a frame */
    float vy;                           /**< its speed, px a frame */
    float spin;                         /**< its turn (drawn as a width that pulses) */
    float spin_v;                       /**< how fast it turns */
    float sway;                         /**< its sway from side to side */
    float sway_v;                       /**< how fast it sways */
    uint8_t w;                          /**< its size, px */
    uint8_t h;                          /**< its size, px */
    uint8_t color;                      /**< its colour (an index) */
} cf_piece_t;

/*
 * Board layout for a variant: boxes and cells inside the GRID_SIZE square at
 * (GRID_X, GRID_Y), centred, with 4 px lines between boxes and 2 px between
 * cells. 9x9: 64 px cells; 6x6 (2x3 boxes): 97 px cells. Cells not on the
 * board (6x6) and boxes it doesn't have are hidden.
 */
#define LINE_THICK 4                    /**< the lines between boxes, px */
#define LINE_THIN  2                    /**< the lines between cells, px */

/* ------------------------------------------------------------- the tour */
/*
 * A first look at the game screen: the board, the pad, the tools, Hint, the
 * top bar and the timer, one at a time, each lit up with the rest dimmed. Once
 * per player (sudoku.db: seen 'tour'), the first time a puzzle is opened;
 * Settings > Game > Game screen tour shows it again. The clock stands still.
 */
#define TOUR_STEPS 6                    /**< the tour's steps */

/* ------------------------------------------------------------- rules card */
/*
 * The ? button in the game's top bar: the rules of the puzzle's variant, with
 * a small drawn example. Shown by itself the first time a variant (other
 * than Classic) is played (store_rules_seen()).
 */
/** @brief A rules card's small drawn example. */
typedef struct {
    uint8_t w;                          /**< its width, cells */
    uint8_t h;                          /**< its height, cells */
    uint8_t bw;                         /**< boxes drawn with thick lines: their width (0 = none) */
    uint8_t bh;                         /**< and height */
    const char *digits;                 /**< w*h: '1'..'9' or '.' */
    const char *tint;                   /**< w*h: '1' = tinted (X, Hyper), may be NULL */
    const char *regions;                /**< w*h region letters: thick lines between them (Jigsaw), may be NULL */
    const char *parity;                 /**< w*h: 'e' shaded, 'o' ring, may be NULL */
    const char *cross;                  /**< w*h: 'x' = can't be the digit (Anti-Knight), may be NULL */
    const uint8_t *bars;                /**< pairs of cells with a bar, ends with 0xFF, may be NULL */
    const uint8_t *thermo;              /**< cells from the bulb, ends with 0xFF, may be NULL */
    const uint8_t *cages;               /**< per cage: sum, cells..., 0xFE; ends with 0xFF; may be NULL */
    int8_t left_clue;                   /**< Sandwich: a sum left of the first row, -1 = none */
    uint8_t edge_kind;                  /**< Kropki, XV, Greater-Than: EDGE_*, with edges */
    const uint8_t *edges;               /**< per mark: a cell and its MARK_* on the line to its right; ends 0xFF */
    const char *quad;                   /**< Quadruple: a circle's digits at the picture's centre, may be NULL */
    uint8_t line_kind;                  /**< the kind of the thermo line: LINE_* (Arrow, Renban, Whispers) */
    int8_t lk_clue;                     /**< Little Killer: a sum above the top-left cell, the diagonal down-right; 0 none */
    const char *left_text;              /**< Outside Sudoku, Rossini: a clue left of the first row as text (left_clue -1), may be NULL */
    const uint8_t *dmarks;              /**< Diagonal Consecutive: per mark a cell and its DMARK_*, ends with 0xFF; may be NULL */
} rules_pic_t;

/* ------------------------------------------------------------- send a puzzle by sound (the format: share_core.h) */
#define PZ_TIMEOUT_MS 90000                       /**< a puzzle's parts must all come within this */
#define PZ_SOURCE    "Received"                   /**< where they're kept: "Received #1", "#2" ... */

/** @brief the received puzzle, while it's checked: the fields of its line and the result */
typedef struct {
    int variant;                                  /**< sudoku_variant_t */
    int level;                                    /**< gen_level_t, -1: rate it */
    uint8_t givens[81];                           /**< the puzzle, 0 = empty */
    char regions[82];                             /**< Jigsaw's regions */
    char cages[STATS_CAGES_LEN];                  /**< Killer's cages */
    char marks[82];                               /**< the marks */
    char thermos[STATS_THERMOS_LEN];              /**< the lines */
    sudoku_geom_t geom;                           /**< its board */
    volatile int graded;                          /**< sudoku_grade: -1 not one solution; -2 still checking */
} pz_got_t;

