/*
 * The screen savers' colours: 3Blue1Brown's (Manim's) palette on black. A colour's _E shade is its
 * deepest, _A its palest; the plain name is the one the videos use most.
 */
#define SV_BLUE_E       0x1C758A    /**< blue, deepest */
#define SV_BLUE_D       0x29ABCA    /**< blue, deep */
#define SV_BLUE         0x58C4DD    /**< blue: 3Blue1Brown's own */
#define SV_BLUE_A       0xC7E9F1    /**< blue, palest */
#define SV_TEAL         0x5CD0B3    /**< teal */
#define SV_GREEN_E      0x699C52    /**< green, deepest */
#define SV_GREEN        0x83C167    /**< green */
#define SV_GREEN_A      0xC9E2AE    /**< green, palest */
#define SV_YELLOW_E     0xE8C11C    /**< yellow, deepest */
#define SV_YELLOW       0xFFFF00    /**< yellow */
#define SV_YELLOW_A     0xFFF1B6    /**< yellow, palest */
#define SV_GOLD         0xF0AC5F    /**< gold */
#define SV_RED_E        0xCF5044    /**< red, deepest */
#define SV_RED          0xFC6255    /**< red */
#define SV_RED_A        0xF7A1A3    /**< red, palest */
#define SV_PINK         0xD147BD    /**< pink */
#define SV_GREY         0x888888    /**< grey */

/**
 * @brief The savers' picture (ui_saver_pic.c): a full-screen black RGB565 image on the cover, in PSRAM.
 * @param[in] parent  the screen saver's cover
 * @return its pixels (SCR_W per row) to paint into, or NULL if there was no memory for it
 */
uint16_t *saver_pic_start(lv_obj_t *parent);
/**
 * @brief Rows of the picture painted: flushed from the CPU's cache, for the DMA that draws it.
 * @param[in] y0  the first row, px
 * @param[in] y1  the last row, px (included)
 */
void saver_pic_flush(int32_t y0, int32_t y1);
/**
 * @brief Part of the picture to redraw (after saver_pic_flush()).
 * @param[in] x0  left, px
 * @param[in] y0  top, px
 * @param[in] x1  right, px (included)
 * @param[in] y1  bottom, px (included)
 */
void saver_pic_redraw(int32_t x0, int32_t y0, int32_t x1, int32_t y1);
/** @brief The savers' picture goes: the image first, then its memory. */
void saver_pic_stop(void);
/**
 * @brief A colour between two (for the savers' fades).
 * @param[in] a  from, 0xRRGGBB
 * @param[in] b  to, 0xRRGGBB
 * @param[in] u  how far, 0 (a) .. 255 (b)
 * @return the colour, RGB565
 */
uint16_t saver_pic_mix(uint32_t a, uint32_t b, int u);
/** @brief A frame of the pen begins: nothing changed yet. */
void saver_pen_begin(void);
/**
 * @brief The pen: a pixel of the picture set (off the screen: nothing).
 * @param[in] x  px
 * @param[in] y  px
 * @param[in] c  the colour (RGB565)
 */
void saver_pen_put(int x, int y, uint16_t c);
/**
 * @brief The pen: a square.
 * @param[in] x  its top left, px
 * @param[in] y  px
 * @param[in] size  its side, px
 * @param[in] c  the colour (RGB565)
 */
void saver_pen_square(int x, int y, int size, uint16_t c);
/**
 * @brief The pen: a round dot of a grid of cells (px - 1 square with the corners off, a 1 px black gap
 *        to the next), as Life, Langton's ant and Brian's Brain draw their cells.
 * @param[in] col  the cell's column
 * @param[in] row  its row
 * @param[in] px  a cell's size, px
 * @param[in] c  the colour (RGB565)
 */
void saver_pen_dot(int col, int row, int px, uint16_t c);
/**
 * @brief The pen: a line.
 * @param[in] x0  from, px
 * @param[in] y0  px
 * @param[in] x1  to, px
 * @param[in] y1  px
 * @param[in] w  its width, px
 * @param[in] c  the colour (RGB565)
 */
void saver_pen_line(int x0, int y0, int x1, int y1, int w, uint16_t c);
/** @brief A frame of the pen ends: what it changed is flushed from the cache and redrawn, tile by tile. */
void saver_pen_end(void);
/**
 * @brief The analog clock screen saver starts (ui_saver_analog.c): a dim face and hands, moved each
 *        minute, updated each second.
 * @param[in] parent  the screen saver's cover
 */
void saver_analog_start(lv_obj_t *parent);
/** @brief The analog clock screen saver stops (its objects go with the cover; nothing if it isn't on). */
void saver_analog_stop(void);

